// Finds the player with this username and password: rules 12-14
public static Player LogIn(string username, string password)
{
    string blank = "";
    if (username.Trim() == "") blank = "Type your username.";
    if (password == "")
    {
        if (blank != "") blank = blank + " ";
        blank = blank + "Type your password.";
    }
    if (blank != "") throw new BlankFieldException(blank);
    List<Player> players = LoadAll();
    foreach (Player p in players)
    {
        if (p.Username.ToLower() == username.Trim().ToLower()
            && p.Password == password)
        {
            return p;
        }
    }
    throw new LoginFailedException();

static class Expedition
{
    public static Player CurrentPlayer;   // who is logged in
}

// Log in: rules 12, 13 and 14, then the welcome screen
private void btnLogIn_Click(object sender, EventArgs e)
{
    lblError.Text = "";
    try
    {
        Player player = PlayerFile.LogIn(txtUsername.Text,
            txtPassword.Text);
        wrongTries = 0;
        Expedition.CurrentPlayer = player;
        this.Hide();
        frmWelcome welcome = new frmWelcome();
        welcome.ShowDialog();       // waits until welcome closes
        txtPassword.Text = "";
        this.Show();
    }

catch (LoginFailedException ex)
{
    wrongTries++;
    txtPassword.Text = "";         // a fresh box for the next try
    txtPassword.Focus();
    if (wrongTries == 3) StartWait();
    else lblError.Text = ex.Message;
}
catch (SummitException ex)
{
    lblError.Text = ex.Message;    // a blank box
}

// Three wrong tries in a row: the button waits 30 seconds
private void StartWait()
{
    lblError.Text = "Three wrong tries. Wait 30 seconds, then try "
        + "again.";
    waitLeft = 30;
    btnLogIn.Enabled = false;
    btnLogIn.Text = "Try again in " + waitLeft + " seconds";
    tmrWait.Start();                   // ticks once a second
}

// Runs every second while the button waits
private void tmrWait_Tick(object sender, EventArgs e)
{
    waitLeft--;
    btnLogIn.Text = "Try again in " + waitLeft + " seconds";
    if (waitLeft == 0)
    {
        tmrWait.Stop();
        wrongTries = 0;
        lblError.Text = "";
        btnLogIn.Text = "Log in";
        btnLogIn.Enabled = true;
    }

// Opens the register form; a new player's name comes back
private void lnkRegister_LinkClicked(object sender,
    LinkLabelLinkClickedEventArgs e)
{
    this.Hide();
    frmRegister register = new frmRegister();
    register.ShowDialog();
    this.Show();
    lblError.Text = "";            // an old message would confuse
    if (register.NewUsername != "")
    {
        txtUsername.Text = register.NewUsername;
        txtPassword.Text = "";
        txtPassword.Focus();       // the cursor waits in Password
    }
}

